oxy_webhelp_navlinks = {"azure_archive_tiering-d39536e10044":{"topics":[{"title":"Azure Cold tier support for archival location","shortdesc":"<p class=\"shortdesc\">When you want to store data for a longer duration and access the data infrequently,         you can transfer the archived data from the Hot or Cool access tier to the Cold access tier         by using the Azure storage lifecycle management policy. Cold tier movement is not managed by         Rubrik. You must configure an Azure lifecycle management policy directly in the Azure         portal.<\/p>","href":"archival\/azure_cold_tier_support_archival_location.html","attributes":{"data-id":"azure_cold_tier_support_archival_location"},"menu":{"hasChildren":false},"tocID":"azure_cold_tier_support_archival_location-d39536e10055","next":"azure_cold_tier_support_archival_location-d39536e10055"},{"title":"Viewing smart tiering details for Azure workloads","shortdesc":"<p class=\"shortdesc\">Viewing SLA Domains in Storage Tiering in <span class=\"ph\">RSC<\/span> is only possible when         they have already been configured in CDM with smart tiering enabled for Azure archival         locations. <span class=\"ph\">RSC<\/span> does not support configuring new smart tiering         policies for SLA Domains.<\/p>","href":"archival\/arch_displaying_smart_tiering_azr.html","attributes":{"data-id":"arch_displaying_smart_tiering_azr"},"menu":{"hasChildren":false},"tocID":"arch_displaying_smart_tiering_azr-d39536e10077","topics":[]},{"title":"Editing smart tiering for Azure workloads","shortdesc":"<p class=\"shortdesc\">You can modify the minimum retention period for snapshots of SLA Domains configured         with smart tiering for Azure workloads. Additionally, you can switch from smart tiering to         other storage tiering options.<\/p>","href":"archival\/arch_editing_smart_tiering_azr.html","attributes":{"data-id":"arch_editing_smart_tiering_azr"},"menu":{"hasChildren":false},"tocID":"arch_editing_smart_tiering_azr-d39536e10094","topics":[]}]}};